<template><q-page class="customer-flow-page"><div class="page-heading"><div><div class="eyebrow">STAFF SERVICES</div><h1 class="page-title">Register a customer</h1><p class="page-subtitle">Create a customer login and a zero-balance account. Record deposits separately.</p></div></div><section class="customer-panel" style="max-width:700px"><q-banner v-if="error" class="bank-feedback q-mb-md" role="alert">{{ error }}</q-banner><div v-if="result"><h2 class="section-heading">Customer registered</h2><p>Username: <strong>{{ result.username }}</strong></p><p>Account: <strong>{{ result.account_number }}</strong></p><p class="page-subtitle">Give the customer their login details privately. They can change their password and enable an authenticator under Profile & security.</p><q-btn color="primary" label="Register another customer" class="q-mt-md" @click="result = null" /></div><q-form v-else class="customer-form" @submit="submit"><q-input v-model.trim="form.first_name" filled label="First name" maxlength="100" :rules="[required]" /><q-input v-model.trim="form.last_name" filled label="Last name" maxlength="100" :rules="[required]" /><q-input v-model.trim="form.username" filled label="Username" maxlength="50" :rules="[v => /^[a-zA-Z0-9_.-]{3,50}$/.test(v) || 'Use 3–50 letters, numbers, dots, dashes or underscores']" /><NewPasswordField v-model="form.password" label="Initial password" /><q-input v-model.trim="form.email" filled type="email" label="Email" :rules="[required]" /><q-input v-model.trim="form.mobile_number" filled label="Mobile number (optional)" maxlength="30" /><DatePickerField v-model="form.date_of_birth" filled label="Date of birth (optional)" clearable /><q-select v-model="form.account_type_id" filled label="Account type" :options="types" emit-value map-options :rules="[required]" /><p class="page-subtitle">Family Savings, Employee, and Business accounts each have one registered owner in this project.</p><q-btn label="Create customer and account" color="primary" type="submit" :loading="busy" :disable="!types.length" /></q-form></section></q-page></template>
<script setup>
import NewPasswordField from '@/components/NewPasswordField.vue'
import DatePickerField from '@/components/DatePickerField.vue'
import { ref, onMounted } from 'vue'
import api from '@/services/api'
const empty = () => ({ first_name: '', last_name: '', username: '', password: '', email: '', mobile_number: '', date_of_birth: null, account_type_id: null })
const form = ref(empty()), types = ref([]), busy = ref(false), error = ref(''), result = ref(null)
const required = v => !!v || 'Required'
onMounted(async () => { try { types.value = (await api.get('/account-types/')).data.map(t => ({label: t.type_name, value: t.id})) } catch { error.value = 'Could not load account types. Refresh to try again.' } })
async function submit () { if (busy.value) return; busy.value = true; error.value = ''; try { result.value = (await api.post('/staff/customers/', { ...form.value, date_of_birth: form.value.date_of_birth || null })).data; form.value = empty() } catch (e) { error.value = e.response?.data?.detail || 'Could not register customer. Please retry.' } finally { busy.value = false } }
</script>
